import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color,
  } = THREE;

  const root = new Group();
  root.name = 'features-card-3';

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const resources = [];
  const timelines = [];
  const primitiveCleanups = [];
  const disposed = new Set();

  const hexToVec3 = (hex) => {
    const value = String(hex).replace('#', '');
    const normalized = value.length === 3
      ? value.split('').map((v) => v + v).join('')
      : value;
    return [
      parseInt(normalized.slice(0, 2), 16) / 255,
      parseInt(normalized.slice(2, 4), 16) / 255,
      parseInt(normalized.slice(4, 6), 16) / 255,
    ];
  };

  const material = (color, transparent = false, opacity = 1) => {
    const mat = new MeshBasicNodeMaterial({
      color: new Color(color),
      transparent,
      opacity,
      depthWrite: !transparent,
    });
    resources.push(mat);
    return mat;
  };

  const gradientStops = Array.isArray(visualSpec.gradientStops)
    ? visualSpec.gradientStops
    : [colors.surface, colors.ink, colors.primary ?? colors.ink];

  const top = hexToVec3(gradientStops[0] ?? colors.ink);
  const middle = hexToVec3(gradientStops[1] ?? colors.surface);
  const bottom = hexToVec3(gradientStops[2] ?? colors.ink);

  const backdropMaterial = material(colors.surface);
  const backdropY = uv().y;
  const topMix = smoothstep(0.48, 1.0, backdropY);
  const bottomMix = smoothstep(0.0, 0.52, backdropY);
  const centerGradient = mix(vec3(bottom[0], bottom[1], bottom[2]), vec3(middle[0], middle[1], middle[2]), bottomMix);
  backdropMaterial.colorNode = mix(
    centerGradient,
    vec3(top[0], top[1], top[2]),
    topMix,
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 5.8),
    backdropMaterial,
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry);

  const shadowMaterial = material(colors.ink, true, 0.48);
  const shadow = new Mesh(
    new PlaneGeometry(2.9, 0.34),
    shadowMaterial,
  );
  shadow.name = 'contact-shadow';
  shadow.position.set(0, -0.88, -0.12);
  shadow.scale.set(1, 0.42, 1);
  root.add(shadow);
  resources.push(shadow.geometry);

  const cardMaterial = material(colors.paper);
  const card = new Mesh(
    new PlaneGeometry(2.45, 1.55),
    cardMaterial,
  );
  card.name = 'brushed-metal-card';
  card.position.set(0, 0, 0.08);
  root.add(card);
  resources.push(card.geometry);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed.has(root)) {
        texture.dispose?.();
        return;
      }
      cardMaterial.map = texture;
      cardMaterial.color.set('#e8ecf2');
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const frameMaterial = material(colors.ink);
  const frame = new Group();
  frame.name = 'machined-frame';

  const topRail = new Mesh(new BoxGeometry(2.62, 0.065, 0.12), frameMaterial);
  const bottomRail = new Mesh(new BoxGeometry(2.62, 0.065, 0.12), frameMaterial);
  const leftRail = new Mesh(new BoxGeometry(0.065, 1.58, 0.12), frameMaterial);
  const rightRail = new Mesh(new BoxGeometry(0.065, 1.58, 0.12), frameMaterial);

  topRail.position.set(0, 0.79, 0.16);
  bottomRail.position.set(0, -0.79, 0.16);
  leftRail.position.set(-1.28, 0, 0.16);
  rightRail.position.set(1.28, 0, 0.16);

  frame.add(topRail, bottomRail, leftRail, rightRail);
  root.add(frame);
  resources.push(
    topRail.geometry,
    bottomRail.geometry,
    leftRail.geometry,
    rightRail.geometry,
  );

  const accentMaterial = material(colors.accent);
  const accent = new Mesh(
    new BoxGeometry(0.58, 0.045, 0.08),
    accentMaterial,
  );
  accent.name = 'signal-red-accent';
  accent.position.set(-0.72, -0.99, 0.22);
  root.add(accent);
  resources.push(accent.geometry);

  const detailMaterial = material(colors.ink, true, 0.72);
  const detail = new Mesh(
    new BoxGeometry(0.92, 0.025, 0.06),
    detailMaterial,
  );
  detail.name = 'machined-detail';
  detail.position.set(0.62, -0.99, 0.21);
  root.add(detail);
  resources.push(detail.geometry);

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed.has(root)) return;
    disposed.add(root);

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}

export default createNode;
